import Foundation
import XCTest
@testable import AITaskMonitor

// Acceptance counterexamples reproduced by macOS CI on fix3. These tests
// have not yet been compiled or run against fix4.
final class ClaudePhaseUnresolvedTests: XCTestCase {
    private func make(_ input: [String: Any], at date: Date) -> [String: Any] {
        var result = ClaudeHook.makeRecord(from: input)
        let formatter = ISO8601DateFormatter()
        formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        result["timestamp"] = formatter.string(from: date)
        return result
    }

    private func write(_ records: [[String: Any]], to file: URL) throws {
        var data = Data()
        for record in records {
            data.append(try JSONSerialization.data(withJSONObject: record))
            data.append(0x0a)
        }
        try data.write(to: file)
    }

    private func create(at date: Date) -> [String: Any] {
        make(["session_id": "synthetic", "hook_event_name": "PostToolUse", "tool_name": "TaskCreate",
              "tool_input": ["subject": "Synthetic step"],
              "tool_response": ["task": ["id": "step-1", "subject": "Synthetic step"]]], at: date)
    }

    private func update(at date: Date) -> [String: Any] {
        make(["session_id": "synthetic", "hook_event_name": "PostToolUse", "tool_name": "TaskUpdate",
              "tool_input": ["taskId": "step-1", "status": "completed"],
              "tool_response": ["success": true, "taskId": "step-1", "updatedFields": ["status"],
                                "statusChange": ["from": "pending", "to": "completed"]]], at: date)
    }

    func testDelayedOldHookAfterRestartCannotClearKnownLoss() throws {
        let dir = FileManager.default.temporaryDirectory.appendingPathComponent("aitm-unresolved-" + UUID().uuidString)
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: dir) }
        let file = dir.appendingPathComponent("claude-events-v2.jsonl")
        let now = Date()
        let marker = make(["session_id": "", "hook_event_name": "AITMSourceUncertain"], at: now.addingTimeInterval(-4))
        // The following two records could be fresh, or generated by an old
        // in-flight hook after monitor restart. Their bytes do not reveal which.
        let prompt = make(["session_id": "synthetic", "hook_event_name": "UserPromptSubmit"], at: now.addingTimeInterval(-2))
        try write([marker, prompt, create(at: now.addingTimeInterval(-1.5)), update(at: now.addingTimeInterval(-1))], to: file)
        let state = try ClaudeTaskReader(eventFile: file).readSnapshot(now: now, observedSince: now.addingTimeInterval(-3))
        let task = try XCTUnwrap(state.tasks.first)
        XCTAssertTrue(state.sourceUncertain)
        XCTAssertFalse(task.planConfirmed, "A restart time alone cannot exclude delayed old hook events")
    }

    func testRetentionCannotSilentlyEraseKnownLossWhileMonitorRuns() throws {
        let dir = FileManager.default.temporaryDirectory.appendingPathComponent("aitm-unresolved-" + UUID().uuidString)
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: dir) }
        let file = dir.appendingPathComponent("claude-events-v2.jsonl")
        let now = Date()
        let marker = make(["session_id": "", "hook_event_name": "AITMSourceUncertain"], at: now.addingTimeInterval(-2 * 86_400))
        let prompt = make(["session_id": "synthetic", "hook_event_name": "UserPromptSubmit"], at: now.addingTimeInterval(-2))
        try write([marker, prompt, create(at: now.addingTimeInterval(-1.5)), update(at: now.addingTimeInterval(-1))], to: file)
        let reader = ClaudeTaskReader(eventFile: file)
        let since = now.addingTimeInterval(-3 * 86_400)
        XCTAssertTrue(try reader.readSnapshot(now: now, observedSince: since).sourceUncertain)
        try ClaudeRetention.clean(directory: dir, backups: dir.appendingPathComponent("backups"), now: now,
                                  policy: ClaudeRetentionPolicy(days: 1, maximumMB: 10))
        let after = try reader.readSnapshot(now: now, observedSince: since)
        XCTAssertTrue(after.sourceUncertain, "Deleting the marker does not restore lost history")
        XCTAssertFalse(after.tasks.first?.planConfirmed == true)
        let restarted = try ClaudeTaskReader(eventFile: file).readSnapshot(now: now, observedSince: since)
        XCTAssertTrue(restarted.sourceUncertain, "Retention must preserve the marker across monitor restart")
        XCTAssertFalse(restarted.tasks.first?.planConfirmed == true)
    }
}
